-- Sample articles (10 per main menu, aligned image/video links)
INSERT OR IGNORE INTO articles (title, slug, content, author_id, category_id, status, featured_image_url, youtube_embed_id, article_type, published_at, view_count) SELECT '제주한라대학교 방송국 샘플 기사 1: 방송국소개', 'broadcast-sample-1', '제주한라대학교 방송국 메뉴의 방송국소개 섹션 기사입니다. 주제와 맞는 이미지와 링크를 연결해 메뉴 점검 및 운영 테스트에 바로 활용할 수 있도록 구성했습니다.', 1, c.category_id, 'published', 'https://images.unsplash.com/photo-1492619375914-88005aa9e8fb?auto=format&fit=crop&w=1200&q=80', 'M7lc1UVf-VE', 'normal', datetime('now','-42 days'), 151 FROM categories c WHERE c.slug = 'broadcast/방송국소개';
INSERT OR IGNORE INTO articles (title, slug, content, author_id, category_id, status, featured_image_url, youtube_embed_id, article_type, published_at, view_count) SELECT '제주한라대학교 방송국 샘플 기사 2: CHEBS뉴스', 'broadcast-sample-2', '제주한라대학교 방송국 메뉴의 CHEBS뉴스 섹션 기사입니다. 주제와 맞는 이미지와 링크를 연결해 메뉴 점검 및 운영 테스트에 바로 활용할 수 있도록 구성했습니다.', 2, c.category_id, 'published', 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&w=1200&q=80', 'jNQXAC9IVRw', 'normal', datetime('now','-41 days'), 152 FROM categories c WHERE c.slug = 'broadcast/CHEBS뉴스';
INSERT OR IGNORE INTO articles (title, slug, content, author_id, category_id, status, featured_image_url, youtube_embed_id, article_type, published_at, view_count) SELECT '제주한라대학교 방송국 샘플 기사 3: 제작프로그램', 'broadcast-sample-3', '제주한라대학교 방송국 메뉴의 제작프로그램 섹션 기사입니다. 주제와 맞는 이미지와 링크를 연결해 메뉴 점검 및 운영 테스트에 바로 활용할 수 있도록 구성했습니다.', 3, c.category_id, 'published', 'https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?auto=format&fit=crop&w=1200&q=80', 'aqz-KE-bpKQ', 'normal', datetime('now','-40 days'), 153 FROM categories c WHERE c.slug = 'broadcast/제작프로그램';
INSERT OR IGNORE INTO articles (title, slug, content, author_id, category_id, status, featured_image_url, youtube_embed_id, article_type, published_at, view_count) SELECT '제주한라대학교 방송국 샘플 기사 4: 언론정보', 'broadcast-sample-4', '제주한라대학교 방송국 메뉴의 언론정보 섹션 기사입니다. 주제와 맞는 이미지와 링크를 연결해 메뉴 점검 및 운영 테스트에 바로 활용할 수 있도록 구성했습니다.', 4, c.category_id, 'published', 'https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?auto=format&fit=crop&w=1200&q=80', 'kJQP7kiw5Fk', 'normal', datetime('now','-39 days'), 154 FROM categories c WHERE c.slug = 'broadcast/언론정보';
INSERT OR IGNORE INTO articles (title, slug, content, author_id, category_id, status, featured_image_url, youtube_embed_id, article_type, published_at, view_count) SELECT '제주한라대학교 방송국 샘플 기사 5: 방송편성표', 'broadcast-sample-5', '제주한라대학교 방송국 메뉴의 방송편성표 섹션 기사입니다. 주제와 맞는 이미지와 링크를 연결해 메뉴 점검 및 운영 테스트에 바로 활용할 수 있도록 구성했습니다.', 5, c.category_id, 'published', 'https://images.unsplash.com/photo-1508214751196-bcfd4ca60f91?auto=format&fit=crop&w=1200&q=80', 'L_jWHffIx5E', 'normal', datetime('now','-38 days'), 155 FROM categories c WHERE c.slug = 'broadcast/방송편성표';
INSERT OR IGNORE INTO articles (title, slug, content, author_id, category_id, status, featured_image_url, youtube_embed_id, article_type, published_at, view_count) SELECT '제주한라대학교 방송국 샘플 기사 6: 수상작·공모전', 'broadcast-sample-6', '제주한라대학교 방송국 메뉴의 수상작·공모전 섹션 기사입니다. 주제와 맞는 이미지와 링크를 연결해 메뉴 점검 및 운영 테스트에 바로 활용할 수 있도록 구성했습니다.', 1, c.category_id, 'published', 'https://images.unsplash.com/photo-1487180144351-b8472da7d491?auto=format&fit=crop&w=1200&q=80', '9bZkp7q19f0', 'normal', datetime('now','-37 days'), 156 FROM categories c WHERE c.slug = 'broadcast/수상작·공모전';
